import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第七卦 师 地水师 坤上坎下","description":"周易 - 第七卦 师 地水师 坤上坎下","frontmatter":{"title":"第七卦 师 地水师 坤上坎下","description":"周易 - 第七卦 师 地水师 坤上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/008.md","filePath":"zh/classics/zhouyi/008.md"}'),l={name:"zh/classics/zhouyi/008.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="师" tabindex="-1">师 <a class="header-anchor" href="#师" aria-label="Permalink to “师”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>贞，丈人，吉无咎。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>师，众也，贞正也，能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>地中有水，师；君子以容民畜众。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>师出以律，否臧凶。象曰：师出以律， 失律凶也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>在师中，吉无咎，王三锡命。象曰：在师中吉，承天宠也。王三锡命，怀万邦也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>师或舆尸，凶。象曰：师或舆尸，大无功也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>师左次，无咎。象曰：左次无咎，未失常也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。象曰：长子帅师，以中行也。弟子舆师，使不当也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>大君有命，开国承家，小人勿用。象曰：大君有命，以正功也。小人勿用，必乱邦也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
